交朋友:
#include <iostream>
#include <cmath>
using namespace std;
int main() {
    int h1, h2, h3, h4;
    cin >> h1 >> h2 >> h3 >> h4;
    int h[] = {h2, h3, h4};
    int best = h2;
    for(int i = 1; i < 3; i++) {
        int d1 = abs(h[i] - h1);
        int d2 = abs(best - h1);
        if (d1 < d2) best = h[i];
        else if (d1 == d2 && h[i] < best) best = h[i];
    }
    cout << best << "\n";
    return 0;
}

